	chain ipv6_input {
		iifname { "lo" } meta l4proto { tcp, udp } th dport 53 accept comment "ipv6-dns"
		meta nfproto ipv6 meta pkttype != host drop comment "ipv6-not-for-the-router"
		meta nfproto ipv6 drop comment "ipv6-default-drop"
	}

	chain forward {
		type filter hook forward priority filter; policy drop;

		meta nfproto ipv6 iifname != { "eth0", "lo", "eth2", "eth2.40" } drop comment "ipv6-not-routed-here"
		meta nfproto ipv6 oifname != { "eth0", "lo", "eth2", "eth2.40" } drop comment "ipv6-not-routed-here"
		meta nfproto ipv6 iifname { "lo", "eth2", "eth2.40" } fib saddr . iif oif missing drop comment "ipv6-lan-spoofed"
		meta nfproto ipv6 iifname { "eth0" } fib saddr oifname { "lo", "eth2", "eth2.40" } drop comment "ipv6-lan-source-from-wan"
		iifname { "eth0" } ip6 saddr fc00::/7 drop comment "ipv6-ula-from-internet"
		iifname { "eth0" } ip6 daddr fc00::/7 drop comment "ipv6-ula-from-internet"
		oifname { "eth0" } ip6 saddr fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-ula-to-internet"
		oifname { "eth0" } ip6 daddr fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-ula-to-internet"
		ip saddr @ids_quarantine drop comment "ids-quarantine-forward"
		meta nfproto ipv6 ether saddr @ids_quarantine_mac drop comment "ids-quarantine-ipv6"
		ct state established,related accept
		ct state invalid drop
		meta nfproto ipv6 iifname { "eth0" } drop comment "ipv6-no-inbound"
		iifname @lan_ifaces tcp dport 853 reject comment "force-dns-block-dot"
		iifname @lan_ifaces udp dport 853 reject comment "force-dns-block-dot"

		iifname @lan_ifaces oifname @wan_ifaces counter accept comment "rule:lan-to-wan"
		iifname @guest_ifaces oifname @wan_ifaces meta l4proto { icmp, ipv6-icmp } counter accept comment "rule:icmp-out"
	}

	chain output {
		type filter hook output priority filter; policy accept;
	}

	chain prerouting {
		type nat hook prerouting priority dstnat; policy accept;

		meta nfproto ipv4 iifname @lan_ifaces udp dport 53 redirect to :53 comment "force-dns"
		meta nfproto ipv4 iifname @lan_ifaces tcp dport 53 redirect to :53 comment "force-dns"
		meta nfproto ipv6 iifname @lan_ifaces udp dport 53 redirect to :53 comment "force-dns"
		meta nfproto ipv6 iifname @lan_ifaces tcp dport 53 redirect to :53 comment "force-dns"
	}

	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;

		meta nfproto ipv4 oifname @wan_ifaces masquerade comment "nat:masquerade:wan"
	}
}

flush ruleset

table inet fr_os {
	set lan_ifaces {
		type ifname
		elements = { "eth1" }
	}
	set wan_ifaces {
		type ifname
		elements = { "eth0" }
	}

	set bruteforce_jail {
		type ipv4_addr
		flags timeout
	}
	set bruteforce_jail6 {
		type ipv6_addr
		flags interval, timeout
	}
	set bruteforce_jail_mac {
		type ether_addr
		flags timeout
	}

	set ids_quarantine {
		type ipv4_addr
		flags timeout
	}
	set ids_quarantine_mac {
		type ether_addr
		flags timeout
	}

	set authenticated_ztna_users {
		type ipv4_addr . ether_addr
		flags dynamic,timeout
		timeout 28800s
	}
	set authenticated_ztna_tunnel {
		type ipv4_addr
		flags dynamic,timeout
		timeout 28800s
	}
	set authenticated_ztna_users6 {
		type ipv6_addr . ether_addr
		flags dynamic,timeout
		timeout 28800s
	}
	set authenticated_ztna_tunnel6 {
		type ipv6_addr
		flags dynamic,timeout
		timeout 28800s
	}

	chain input {
		type filter hook input priority filter; policy drop;

		ip saddr @bruteforce_jail drop comment "bruteforce-jail"
		ip saddr @ids_quarantine drop comment "ids-quarantine"
		ip6 saddr @bruteforce_jail6 tcp dport { 22, 443 } drop comment "bruteforce-jail6"
		ether saddr @bruteforce_jail_mac tcp dport { 22, 443 } drop comment "bruteforce-jail-mac"
		meta nfproto ipv6 ether saddr @ids_quarantine_mac drop comment "ids-quarantine-ipv6"
		iifname "lo" accept
		iifname { "eth0" } icmpv6 type { nd-neighbor-solicit, nd-neighbor-advert } ip6 hoplimit 255 accept comment "ipv6-nd"
		iifname { "eth0" } ip6 saddr fe80::/10 icmpv6 type nd-router-advert ip6 hoplimit 255 accept comment "ipv6-ra"
		iifname { "eth0" } ip6 saddr fe80::/10 icmpv6 type mld-listener-query ip6 hoplimit 1 accept comment "ipv6-mld"
		iifname { "eth0" } icmpv6 type { destination-unreachable, packet-too-big, time-exceeded, parameter-problem } accept comment "ipv6-errors"
		iifname { "eth0" } icmpv6 type echo-request limit rate 5/second burst 10 packets accept comment "ipv6-ping"
		iifname { "eth0" } ip6 saddr fe80::/10 udp sport 547 udp dport 546 accept comment "ipv6-dhcpv6-client"
		iifname { "eth1" } icmpv6 type { nd-neighbor-solicit, nd-neighbor-advert, nd-router-solicit } ip6 hoplimit 255 accept comment "ipv6-lan-nd"
		iifname { "eth1" } icmpv6 type echo-request limit rate 5/second burst 10 packets accept comment "ipv6-lan-ping"
		ct state established,related accept
		ct state invalid drop
		meta nfproto ipv6 jump ipv6_input
		iifname @wan_ifaces tcp dport { 22, 443 } drop comment "no-management-from-wan"

		limit rate 10/minute burst 10 packets log prefix "fr_os/drop/input: " comment "log-default-drop"
	}

	chain ipv6_input {
		meta nfproto ipv6 meta pkttype != host drop comment "ipv6-not-for-the-router"
		meta nfproto ipv6 limit rate 10/minute burst 10 packets log prefix "fr_os/drop/input: " comment "log-ipv6-drop"
		meta nfproto ipv6 drop comment "ipv6-default-drop"
	}

	chain forward {
		type filter hook forward priority filter; policy drop;

		meta nfproto ipv6 iifname != { "eth0", "eth1" } drop comment "ipv6-not-routed-here"
		meta nfproto ipv6 oifname != { "eth0", "eth1" } drop comment "ipv6-not-routed-here"
		meta nfproto ipv6 iifname { "eth1" } fib saddr . iif oif missing drop comment "ipv6-lan-spoofed"
		meta nfproto ipv6 iifname { "eth0" } fib saddr oifname { "eth1" } drop comment "ipv6-lan-source-from-wan"
		iifname { "eth0" } ip6 saddr fc00::/7 drop comment "ipv6-ula-from-internet"
		iifname { "eth0" } ip6 daddr fc00::/7 drop comment "ipv6-ula-from-internet"
		oifname { "eth0" } ip6 saddr fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-ula-to-internet"
		oifname { "eth0" } ip6 daddr fc00::/7 reject with icmpv6 type admin-prohibited comment "ipv6-ula-to-internet"
		ip saddr @ids_quarantine drop comment "ids-quarantine-forward"
		meta nfproto ipv6 ether saddr @ids_quarantine_mac drop comment "ids-quarantine-ipv6"
		iifname { "eth1" } udp dport 443 reject comment "sni-filter-no-quic"
		ct state established,related accept
		ct state invalid drop
		meta nfproto ipv6 iifname { "eth0" } oifname @lan_ifaces ip6 daddr & ::ffff:ffff:ffff:ffff == ::5054:ff:fe12:3456 tcp dport 443 counter accept comment "pinhole:nas-https"
		meta nfproto ipv6 iifname { "eth0" } limit rate 10/minute burst 10 packets log prefix "fr_os/drop/forward: " comment "log-ipv6-inbound"
		meta nfproto ipv6 iifname { "eth0" } drop comment "ipv6-no-inbound"

		iifname @lan_ifaces oifname @wan_ifaces counter accept comment "rule:lan-to-wan"

		limit rate 10/minute burst 10 packets log prefix "fr_os/drop/forward: " comment "log-default-drop"
	}

	chain output {
		type filter hook output priority filter; policy accept;
	}

	chain prerouting {
		type nat hook prerouting priority dstnat; policy accept;
	}

	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;

		meta nfproto ipv4 oifname @wan_ifaces masquerade comment "nat:masquerade:wan"
	}
}
